Let $S = \bC\bs{x_{1}, \ldots, x_{N}}$ denote the polynomial ring, graded by degree $S = \bigoplus_{i \geq 0} S_{i}$.
Given a vector space $V \subset S$, we use $V_{i}$ to denote the degree $i$ piece, that is, $V_{i} = V \cap S_{i}$.
We say that a vector space is graded if $V = \oplus V_{i}$.

We use \emph{form} to refer to a homogeneous polynomial.
Given two forms $A, B$ we say that $A, B$ are non-associate if $A \not \in \ideal{B}$ and $B \not \in \ideal{A}$.
If $A, B$ are of the same degree, this is equivalent to them being linearly independent.

\begin{definition}
 A polynomial $P\in \bF[x_1,\cdots,x_N]$ is called \emph{absolutely irreducible} if $P$ is irreducible in the polynomial ring $\overline{\bF}[x_1,\cdots,x_n]$, over an algebraic closure $\overline{\bF}$ of $\bF$.
\end{definition}

Let $S = \bK[x_{1}, \dots, x_{n}, y_{1}, \dots, y_{m}]$ be a graded polynomial ring with $\deg(x_i)=d_i\geq 1$ and  $\deg(y_j)=e_j\geq 1$. 
Let $A=\bK[x_1,\cdots,x_n]$ and $K(A)$ the fraction field of $A$. 
Let $d\geq 1$ and $P \in S_d \setminus \ideal{x_{1}, \dots, x_{n}}$ such that $P$ is absolutely irreducible over $K(A)$.

\begin{theorem}[{\cite[Theorem~4.16]{GOS24}}]
\label{lem:primebound}
There are at most $\primebound{d}$ pairwise non-associate irreducible homogeneous elements $Q_{i} \in A$ such that $\ideal{P, Q_{i}}$ is not prime. 
\end{theorem}

\begin{proposition}
\label{lem:absredcount}
There are at most $\irredprimebound{d}$ elements $Q_{i} \in A$ such that $P + Q_{i}$ is absolutely reducible over $K(A)$.
\end{proposition}

\begin{corollary}
